import{H as e,_t as t,at as n,et as r,it as i,ot as a,rt as o,xt as s}from"./chunks/framework.Bcve9O8f.js";var c=JSON.parse(`{"title":"The quantum field — one receipt","description":"","frontmatter":{"title":"The quantum field — one receipt","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"The quantum field — one receipt | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/quantum.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"The quantum field — one receipt | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/quantum.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/quantum.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/quantum.html"}]]},"headers":[],"relativePath":"quantum.md","filePath":"quantum.md"}`),l={name:`quantum.md`};function u(e,c,l,u,d,f){let p=s(`QuantumField`);return t(),o(`div`,null,[c[0]||=r(`h1`,{id:`the-quantum-field`,tabindex:`-1`},[n(`The quantum field `),r(`a`,{class:`header-anchor`,href:`#the-quantum-field`,"aria-label":`Permalink to “The quantum field”`},`​`)],-1),c[1]||=r(`p`,null,[n(`This page renders `),r(`a`,{href:`https://github.com/ceccec/millennium-solutions/blob/main/src/proof/quantum.lean`,target:`_blank`,rel:`noreferrer`},[r(`code`,null,`src/proof/quantum.lean`)]),n(` in three dimensions. Nothing in the scene is decoration: every coordinate is a value the Lean file decides over, and a gate recomputes all five figures on each build, reading what they `),r(`em`,null,`should`),n(` be out of the theorem statements themselves rather than from a number typed into the check.`)],-1),a(p),c[2]||=i(`<h2 id="what-you-are-looking-at" tabindex="-1">What you are looking at <a class="header-anchor" href="#what-you-are-looking-at" aria-label="Permalink to “What you are looking at”">​</a></h2><p>Each sphere is one <strong>ordering</strong> of the doubling orbit <code>[1, 2, 4, 8]</code> — one observer&#39;s sequence. <code>perms_of_four_is_factorial</code> decides there are exactly 4! = 24 of them, and 24 is what the scene draws.</p><p>Its <strong>height</strong> is the value the <em>control</em> fold returns for that ordering — the same combination performed without canonicalising first. Those heights land on five distinct levels, which is <code>the_uncanonicalised_fold_gives_many_answers</code>. That number is the size of the problem, measured: a fold that reads its input in the order it arrives gives five different answers to the same question.</p><p>Every sphere is joined to <strong>one node</strong>. <code>superposition_collapses_to_one</code> decides that all 24 orderings produce a single receipt. Many perspectives, held at once, resolving to one address.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><p>The mechanism is named in the file as a theorem, so the picture cannot be read as a claim about physics: <code>the_invariance_is_canonicalisation_not_physics</code> decides that every ordering <em>sorts to the same list</em>, and the receipt reads only that. There is no hardware here, no speedup and no qubit. The word &quot;quantum&quot; names a structural property — a set of perspectives held at once, collapsing to one value — and the file proves that property is a <strong>sort</strong>.</p><p>The limit is proved too, in the same file and shown in the caption. A receipt lands in ℤ/9, so nine values must cover every possible set: <code>the_receipt_is_not_injective</code> decides that 45 two-element multisets share 9 receipts. Order-invariant does not mean collision-free, and a receipt that cannot tell 45 things apart must never be read as naming one of them. — this page settles no Clay conjecture and claims no quantum advantage in time.</p>`,7)])}var d=e(l,[[`render`,u]]);export{c as __pageData,d as default};